 document.getElementById('cr-photo').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{const data=await compressCreatorImage(file);document.getElementById('cr-photo-data').value=data;document.getElementById('cr-photo-status').textContent='Photo ready';document.getElementById('creator-photo-preview').innerHTML=`<img src="${data}" alt="Creator preview" style="width:96px;height:96px;object-fit:cover;border-radius:16px;border:1px solid #e6e7eb">`}catch(err){toast(err.message||'Could not process image','error')}};
 document.getElementById('add-creator-batch').onclick=()=>{if(S.creatorBatch.length>=100){toast('Maximum 100 creators per batch.','error');return}const x=creatorFormCollect();if(!x.name||!x.channel||!x.primaryChannelLink||!x.bio){toast('Creator name, channel, profile link and creator description are required.','error');return}if(Object.values(x.intelligence).some(v=>!v.length)){toast('Creator intelligence could not be derived. Add a short creator description.','error');return}S.creatorBatch.push(x);toast(`${x.name} added to batch`,'good');document.getElementById('creator-form').reset();document.getElementById('cr-photo-data').value='';document.getElementById('creator-photo-preview').innerHTML='';document.querySelectorAll('[data-chip]').forEach(b=>b.classList.remove('selected'));document.querySelectorAll('.signal-other').forEach(i=>i.value='');document.getElementById('save-creator-batch').textContent=`Save batch (${S.creatorBatch.length})`;renderBatch()};
 document.getElementById('save-creator-batch').onclick=async()=>{if(!S.creatorBatch.length){const x=creatorFormCollect();if(x.name&&x.channel&&x.primaryChannelLink&&x.bio&&Object.values(x.intelligence).every(v=>v.length))S.creatorBatch.push(x);else{toast('Complete the creator name, channel, profile link and creator description.','error');return}}const btn=document.getElementById('save-creator-batch');btn.disabled=true;btn.textContent='Processing…';try{for(const x of S.creatorBatch){const payload={channel:x.channel,secondaryChannel:x.secondaryChannel,followers:x.followers,er:x.er,rate:x.rate,primaryChannelLink:x.primaryChannelLink,profileUrl:x.primaryChannelLink,profileImageUrl:x.profileImageUrl,bio:x.bio,intelligence:x.intelligence,intelligenceSource:x.intelligenceSource};const q=await sb.from('creators').insert({organization_id:S.org.id,name:x.name,payload}).select().single();if(q.error)throw q.error}S.creatorBatch=[];await refresh();toast('Creator batch saved','good');renderPage()}catch(err){toast(err.message||'Could not save creator batch','error')}finally{btn.disabled=false;btn.textContent='Save batch'}};
 document.getElementById('save-shortlist').onclick=async()=>{if(!S.selectedCampaign){toast('Create a campaign first.','error');return}const ids=[...document.querySelectorAll('[data-shortlist-creator]:checked')].map(x=>x.dataset.shortlistCreator);const payload={...(S.selectedCampaign.payload||{}),decisionShortlistIds:ids,decisionShortlistUpdatedAt:new Date().toISOString()};const q=await sb.from('campaigns').update({payload,updated_at:new Date().toISOString()}).eq('id',S.selectedCampaign.id).select().single();if(q.error){toast(q.error.message,'error');return}S.selectedCampaign=q.data;const i=S.campaigns.findIndex(x=>x.id===q.data.id);if(i>=0)S.campaigns[i]=q.data;toast(`${ids.length} creator${ids.length===1?'':'s'} moved to Decision`,'good');S.page=3;renderPage()};
