function downloadReportCSV(){if(reportExportIsTrial()){showPaidExportGate();return}const p=buildReportExportPayload(),rows=[['Section','Field','Value','Creator','Decision']];const push=(section,field,value,creator='',decision='')=>rows.push([section,field,value==null?'':String(value),creator,decision]);const c=p.campaign||{};const cp=c.payload||{};push('Campaign','Name',c.name);push('Campaign','Status',c.status);push('Campaign','Objective',cp.objective||cp.goal);push('Campaign','Budget',cp.budget);push('Campaign','Market',cp.market);push('Audience','Type',p.audience?.payload?.audienceType);push('Audience','Persona',p.audience?.payload?.audiencePersona);(p.approvedCreators||[]).forEach(x=>push('Creator Decision','Score',x.decision?.score,x.creator?.name,x.decision?.decision));(p.performance||[]).forEach(x=>{push('Performance','Observed At',x.observed_at,x.creator_id);push('Performance','Spend THB',x.spend_thb,x.creator_id);push('Performance','Revenue THB',x.revenue_thb,x.creator_id);push('Performance','Reach',x.reach,x.creator_id);push('Performance','Views',x.views,x.creator_id);push('Performance','Clicks',x.clicks,x.creator_id);push('Performance','Conversions',x.conversions,x.creator_id)});Object.entries(p.businessImpact||{}).forEach(([k,v])=>push('Business Impact',k,v));push('Learning','Worked',p.learning?.worked);push('Learning','Friction',p.learning?.friction);push('Learning','Hypothesis',p.learning?.hypothesis);(p.learning?.nextActions||[]).forEach((x,i)=>push('Learning',`Next Action ${i+1}`,x));const csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`KOL-IDS-${String(S.selectedCampaign?.name||'Campaign').replace(/[^A-Za-z0-9-_]+/g,'-')}-Report.csv`;a.click();URL.revokeObjectURL(a.href)}
